parameters.query:
UPDATE unique_orders SET
  dispatch_status = '{{ $json.dispatchStatus || "Dispatched" }}',
  dispatch_method = '{{ $json.dispatchMethod }}',
  waybill_number = {{ $json.waybillNumber ? "'" + $json.waybillNumber + "'" : "NULL" }}
WHERE order_id = {{ parseInt($json.orderId.replace(/\\D/g, '')) }};

parameters.jsCode:
// Get all items from input
const items = $input.all();
const firstItem = items[0].json.data ? items[0].json.data[0] : items[0].json;

// Determine dispatch type
const isCollection = firstItem.dispatchMethod === 'Collection' || firstItem.dispatchMethod === 'Pickup';

// Build items HTML
let itemsHtml = '';
const allData = items[0].json.data || [firstItem];
for (const data of allData) {
  itemsHtml += `
    <tr>
      <td style="padding: 15px 0; border-bottom: 1px solid #eeeeee;">
        <h3 style="margin: 0 0 5px 0; color: #333333; font-size: 16px;">${data.deviceType}</h3>
        <p style="margin: 0; color: #666666; font-size: 13px;">Qty: ${data.quantityOrdered}</p>
      </td>
    </tr>
  `;
}

const headerTitle = isCollection ? 'Order Ready for Collection' : 'Order Dispatched';
const alertMessage = isCollection 
  ? `Please collect your order from: ${firstItem.warehouseFulfilling}`
  : `Your order will be dispatched via ${firstItem.deliveryParty}`;

return [{
  json: {
    headerTitle: headerTitle,
    recipientName: firstItem.recipientName,
    recipientEmail: firstItem.recipientEmail,
    orderId: firstItem.orderId,
    alertMessage: alertMessage,
    dateOrdered: firstItem.dateOrdered,
    totalItems: firstItem.totalItems,
    totalQuantity: firstItem.totalQuantity,
    orderedBy: firstItem.orderedBy,
    warehouseFulfilling: firstItem.warehouseFulfilling,
    region: firstItem.region,
    recipientAddress: firstItem.recipientAddress,
    recipientContactNumber: firstItem.recipientContactNumber,
    waybillNumber: firstItem.waybillNumber,
    itemsHtml: itemsHtml
  }
}];
